import json,pathlib,hashlib
B=pathlib.Path('audits/VISION_P1_FOUR_CRABS_20260920');out=B/'intake-01'
def make(id,root,carapace,legs,claws,eyes):
 master=B/id/'generation-01'/f'{id}-master.png';l={'root':root,'carapace':carapace};parts=[]
 for name,r,k,f,up,down in legs:
  l.update({name+'Root':r,name+'Knee':k,name+'Foot':f});layer='far' if name.endswith('Far') else 'near'
  parts.extend([{'id':name.lower()+'-upper','joint':name+'Knee','layer':layer,'poly':up},{'id':name.lower()+'-lower','joint':name+'Foot','layer':layer,'poly':down}])
 for side,points,arm,palm,finger in claws:
  l.update({'claw'+side+j:p for j,p in zip(['Base','Elbow','Palm','FixedRoot','FixedTip','DactylRoot','DactylTip'],points)})
  parts.extend({'id':'claw-'+side.lower()+'-'+suffix,'joint':'claw'+side+joint,'layer':'near','poly':poly} for suffix,joint,poly in [('arm','Elbow',arm),('palm','Palm',palm),('finger','DactylRoot',finger)])
 for side,r,t,poly in eyes:
  l['eye'+side+'Root']=r;l['eye'+side+'Tip']=t;parts.append({'id':'eye-'+side.lower(),'joint':'eye'+side+'Tip','layer':'near','poly':poly})
 spec={'schema':'cf.p1-painted-observation/v1','id':id,'master':str(master),'masterSha256':hashlib.sha256(master.read_bytes()).hexdigest(),'size':1254,'groundLineY':max(x[3][1] for x in legs)+8,'landmarksPx':l,'parts':parts,'anatomyDeclaration':'complete inventory; no hidden or absent field','alphaPolicy':'all delivered RGBA channels preserved','sourceLabelsReused':False,'sourceLandmarksReused':False,'artAcceptance':'pending Nick; intake authorized','observationNote':'Projected endpoints observed on painted segments; proximal attachments obscured by carapace placed at their visible emergence. No guide coordinates reused.'}
 (out/f'{id}-observation.json').write_text(json.dumps(spec,indent=2)+'\n')
